const $=id=>document.getElementById(id);
let api="",token="",user=null,exams=[],drafts=[],active=null,answers=[],marked=new Set(),questionIndex=0,deadline=0,tick=null,currentReport=null,camStream=null,faceModelReady=false,proctorTimer=null,absenceFrames=0,multiFrames=0,proctorBusy=false,alertTimes={},liveRefreshTimer=null,livePollTimer=null,studentLivePeers=new Map(),adminLivePeers=new Map(),seenLiveOffers=new Set(),pendingExam=null,examMediaConsent=false,paletteFilter="All",visitedQuestions=new Set(),studentChatTimer=null,adminAudioStream=null,adminVideoStream=null,pollingLiveOffers=false;
function status(id,msg,kind=""){const el=$(id);if(!el)return;el.textContent=msg;el.className="status "+kind}
async function request(path,opts={}){const headers={"Content-Type":"application/json",...(token?{Authorization:"Bearer "+token}:{}),...(opts.headers||{})};const r=await fetch(api+path,{...opts,headers});const data=await r.json().catch(()=>({error:"Unexpected response"}));if(!r.ok)throw new Error(data.error||"Request failed ("+r.status+")");return data}
function globalMessage(msg,isError=false){const el=$("globalStatus");if(!el)return;el.textContent=msg;el.className="status "+(isError?"bad":"ok");el.classList.remove("hide")}
function enterPortal(){ $("authArea").classList.add("hide");$("portal").classList.remove("hide");$("examView").classList.add("hide");$("reportView").classList.add("hide");$("logout").classList.remove("hide");$("userPill").textContent=user.email;$("userPill").classList.remove("hide");
 const admin=user.role==="admin";$("studentNav").classList.toggle("hide",admin);$("adminNav").classList.toggle("hide",!admin);$("navRole").textContent=admin?"ADMIN WORKSPACE":"STUDENT WORKSPACE";
 if(admin){showPage("admin-home");$("adminAccountEmail").textContent="Signed in as "+user.email;loadDashboard();loadStudents();loadFees();loadVideos(true);loadExams();loadAnalytics();loadStorageStatus();}
 else{showPage("student-home");$("studentHello").textContent="Welcome"+(user.fullName?" "+user.fullName.split(" ")[0]:"");loadExams();loadVideos(false);loadStudentAnalysis();loadStudentFees();loadProfile();}
}
function showPage(id){document.querySelectorAll(".page").forEach(el=>el.classList.toggle("active",el.id===id));document.querySelectorAll(".nav button").forEach(el=>el.classList.toggle("active",el.dataset.page===id));if(liveRefreshTimer){clearInterval(liveRefreshTimer);liveRefreshTimer=null}
 if(id==="admin-home")loadDashboard();if(id==="admin-students")loadStudents();if(id==="admin-tests")loadExams();if(id==="admin-live"){loadLive();loadAdminChat();liveRefreshTimer=setInterval(()=>{if($("admin-live").classList.contains("active")){loadLive();loadAdminChat()}},4000)}if(id==="admin-fees")loadFees();if(id==="admin-videos")loadVideos(true);if(id==="admin-analytics")loadAnalytics();if(id==="student-videos")loadVideos(false);if(id==="student-tests")loadExams();if(id==="student-analysis")loadStudentAnalysis();if(id==="student-fees")loadStudentFees();if(id==="student-account")loadProfile();}
async function connect(){api=($("apiOrigin").value.trim()||window.location.origin).replace(/\/+$/,"");if(!/^https?:\/\//i.test(api)){status("apiStatus","Enter a valid API URL including https://.","bad");return}try{const r=await fetch(api+"/api/health");if(!r.ok)throw new Error("Health check returned "+r.status);const d=await r.json();$("apiPill").textContent="API "+d.version+" online";status("apiStatus","Connected to "+d.service+" · "+d.version,"ok");$("config").classList.add("hide");$("login").classList.remove("hide");$("loginStatus").textContent="Use the email and password assigned by your administrator."}catch(e){status("apiStatus","Could not connect: "+e.message,"bad")}}
async function login(){try{const d=await request("/api/auth/login",{method:"POST",body:JSON.stringify({email:$("email").value,password:$("password").value})});token=d.token;user=d.user;$("password").value="";enterPortal()}catch(e){status("loginStatus",e.message,"bad")}}
function renderItems(id,rows,empty="No records yet."){const el=$(id);if(!el)return;el.replaceChildren();if(!rows.length){const p=document.createElement("p");p.className="muted";p.textContent=empty;el.append(p);return}rows.forEach(r=>{const d=document.createElement("div");d.className="item";const left=document.createElement("div");left.className="left";const b=document.createElement("b"),p=document.createElement("p");b.textContent=r.title;p.textContent=r.desc||"";left.append(b,p);d.append(left);if(r.tag){const tag=document.createElement("span");tag.className="tag "+(r.kind||"");tag.textContent=r.tag;d.append(tag)}if(r.action)d.append(r.action);el.append(d)})}
function makeButton(label,fn,kind="secondary"){const b=document.createElement("button");b.textContent=label;b.className=kind;b.onclick=fn;return b}
async function loadExams(){try{const d=await request("/api/exams");exams=d.exams||[];const studentList=$("examList");if(studentList){studentList.replaceChildren();const available=exams.filter(e=>e.status==="published");if(!available.length){studentList.textContent="No published tests are available yet. Check again later."; }else available.forEach(e=>{const item=document.createElement("div");item.className="item";const left=document.createElement("div");left.className="left";const title=document.createElement("b"),desc=document.createElement("p");title.textContent=e.title;desc.textContent=e.question_count+" questions · "+e.duration_minutes+" min · "+e.status;left.append(title,desc);item.append(left,makeButton("Start test",()=>startExam(e),e.question_count===180?"":"secondary"));if(e.question_count!==180)item.lastChild.disabled=true;studentList.append(item)})}
 const adminList=$("adminExamList");if(adminList&&user?.role==="admin"){adminList.replaceChildren();if(!exams.length)adminList.textContent="No exams yet. Create a draft below.";exams.forEach(e=>{const item=document.createElement("div");item.className="item";const left=document.createElement("div");left.className="left";const b=document.createElement("b"),p=document.createElement("p");b.textContent=e.title;p.textContent=e.question_count+" questions · "+e.duration_minutes+" min · "+e.status;left.append(b,p);item.append(left);item.append(makeButton("Preview",()=>previewExam(e.id)));if(e.status==="draft")item.append(makeButton("Delete draft",()=>deleteExam(e), "danger"));if(e.status==="published")item.append(makeButton("Archive",()=>archiveExam(e),"secondary"));adminList.append(item)})}
 await loadDrafts();}catch(e){globalMessage(e.message,true)}}
async function loadDrafts(preferredId=""){if(user?.role!=="admin")return;try{const all=await request("/api/exams");drafts=all.exams.filter(e=>e.status==="draft");const sel=$("draftExam"),previous=preferredId||sel.value;sel.replaceChildren();drafts.forEach(e=>{const o=document.createElement("option");o.value=e.id;o.textContent=e.title+" ("+e.question_count+" questions)";sel.append(o)});if(!drafts.length){const o=document.createElement("option");o.textContent="Create a draft exam first";o.value="";sel.append(o)}else if(drafts.some(e=>e.id===previous))sel.value=previous;else sel.value=drafts.find(e=>e.question_count===180)?.id||drafts[0].id;}catch(e){status("createStatus",e.message,"bad")}}
async function createExam(){try{const d=await request("/api/admin/exams",{method:"POST",body:JSON.stringify({title:$("examTitle").value,durationMinutes:Number($("examDuration").value)})});status("createStatus","Draft created: "+d.exam.title,"ok");await loadExams();$("draftExam").value=d.exam.id;showPage("admin-tests")}catch(e){status("createStatus",e.message,"bad")}}
async function importBank(){const f=$("bankFile").files[0],id=$("draftExam").value;if(!f||!id){status("importStatus","Choose a draft and a JSON file first.","bad");return}try{const parsed=JSON.parse(await f.text()),questions=Array.isArray(parsed)?parsed:parsed.questions;if(!Array.isArray(questions))throw new Error("File must contain a questions array.");const d=await request("/api/admin/exams/"+id+"/questions/import",{method:"POST",body:JSON.stringify({questions})});status("importStatus","Imported "+d.imported+" questions · Physics "+d.subjects.Physics+", Chemistry "+d.subjects.Chemistry+", Biology "+d.subjects.Biology,"ok");await loadExams();$("draftExam").value=id;globalMessage("Question bank imported into the selected draft.",false)}catch(e){status("importStatus",e.message,"bad")}}
async function publishExam(){const id=$("draftExam").value;if(!id){status("publishStatus","Create or select a draft exam first.","bad");return}try{const d=await request("/api/admin/exams/"+id+"/publish",{method:"POST"});status("publishStatus","Published successfully. Verified 180 questions: Physics 45, Chemistry 45, Biology 90.","ok");await loadExams();showPage("admin-tests")}catch(e){status("publishStatus",e.message,"bad")}}
async function deleteExam(e){if(!confirm('Delete draft "'+e.title+'"? This cannot be undone.'))return;try{await request("/api/admin/exams/"+e.id,{method:"DELETE"});globalMessage("Draft deleted.",false);await loadExams()}catch(err){globalMessage(err.message,true)}}
async function archiveExam(e){if(!confirm('Archive "'+e.title+'"? It will no longer be offered to students, and existing records are retained.'))return;try{await request("/api/admin/exams/"+e.id+"/archive",{method:"POST",body:"{}"});globalMessage("Exam archived; historical sessions are retained.",false);await loadExams()}catch(err){globalMessage(err.message,true)}}
async function previewExam(id){$("previewTitle").textContent="Loading preview…";$("previewQuestions").replaceChildren();$("previewModal").classList.remove("hide");try{const d=await request("/api/admin/exams/"+id+"/preview");$("previewTitle").textContent=d.exam.title+" · "+d.questions.length+" questions";status("previewStatus",d.exam.status+" · "+d.exam.duration_minutes+" minutes · Admin preview includes answer keys.","ok");if(!d.questions.length){$("previewQuestions").textContent="No questions imported yet.";return}d.questions.forEach(q=>{const card=document.createElement("div");card.className="videoCard";const h=document.createElement("b");h.textContent="Q"+q.position+" · "+q.subject+" · "+q.chapter;const p=document.createElement("p");p.textContent=q.prompt;card.append(h,p);q.options.forEach((o,i)=>{const op=document.createElement("div");op.textContent=String.fromCharCode(65+i)+". "+o+(i===q.answer_index?" ✓ Correct answer":"");op.style.padding="4px 0";if(i===q.answer_index)op.style.fontWeight="700";card.append(op)});if(q.explanation){const ex=document.createElement("p");ex.textContent="Explanation: "+q.explanation;card.append(ex)}$("previewQuestions").append(card)})}catch(e){status("previewStatus",e.message,"bad")}}
async function loadDashboard(){try{const d=await request("/api/admin/dashboard"),studentsData=await request("/api/admin/students");$("adminMetrics").replaceChildren();[["Students",studentsData.students.length],["Total sessions",d.summary.totalSessions||0],["Active tests",d.summary.activeSessions||0],["Submitted",d.summary.submittedSessions||0],["Average score",d.summary.averageScore??"—"]].forEach(([label,val])=>{const el=document.createElement("div");el.className="metric";const b=document.createElement("b"),s=document.createElement("span");b.textContent=val;s.textContent=label;el.append(b,s);$("adminMetrics").append(el)});renderItems("recentSessions",d.recentSessions.map(s=>({title:(s.candidate||"Student")+" · "+s.exam,desc:s.status+" · score "+(s.score??"—")+" · "+s.started_at,tag:s.status,kind:s.status==="in_progress"?"amber":"green"})));renderItems("alerts",d.alerts.map(a=>({title:a.event_type+" · "+a.severity,desc:a.candidate+" · "+a.occurred_at+" · "+a.detail,tag:a.severity,kind:a.severity==="high"?"red":"amber"})))}catch(e){globalMessage(e.message,true)}}
async function loadStudents(){if(user?.role!=="admin")return;try{const d=await request("/api/admin/students");$("studentList").replaceChildren();if(!d.students.length){$("studentList").textContent="No student accounts yet.";return}d.students.forEach(s=>{const item=document.createElement("div");item.className="item";const left=document.createElement("div");left.className="left";const b=document.createElement("b"),p=document.createElement("p"),tags=document.createElement("div");b.textContent=(s.full_name||"Name not provided")+" · "+s.email;p.textContent=(s.batch||"General")+" · "+(s.phone||"No phone")+" · "+s.attempts+" attempts · Fees ₹"+s.amount_paid+" / ₹"+s.amount_due;tags.className="statline";const t=document.createElement("span");t.className="tag "+(s.active?"green":"red");t.textContent=s.active?"Active":"Deactivated";tags.append(t);left.append(b,p,tags);item.append(left,makeButton("Edit details",()=>editStudent(s)),makeButton(s.active?"Deactivate":"Reactivate",()=>toggleStudent(s),"secondary"));$("studentList").append(item)})}catch(e){globalMessage(e.message,true)}}
async function editStudent(s){const fullName=prompt("Student full name:",s.full_name||"");if(fullName===null)return;const phone=prompt("Phone:",s.phone||"");if(phone===null)return;const batch=prompt("Batch:",s.batch||"General");if(batch===null)return;const guardianContact=prompt("Parent/guardian contact:",s.guardian_contact||"");if(guardianContact===null)return;try{await request("/api/admin/students/"+s.id,{method:"PUT",body:JSON.stringify({fullName,phone,batch,guardianContact,active:!!s.active})});globalMessage("Student details updated.",false);await loadStudents()}catch(e){globalMessage(e.message,true)}}
async function toggleStudent(s){const active=!s.active;if(!confirm((active?"Reactivate":"Deactivate")+" account for "+s.email+"?"))return;try{await request("/api/admin/students/"+s.id,{method:"PUT",body:JSON.stringify({fullName:s.full_name,phone:s.phone,batch:s.batch,guardianContact:s.guardian_contact,active})});globalMessage(active?"Student account reactivated.":"Student account deactivated; login is blocked.",false);await loadStudents()}catch(e){globalMessage(e.message,true)}}
async function createCandidate(){try{const body={email:$("candidateEmail").value.trim(),password:$("candidatePassword").value,fullName:$("candidateName").value.trim(),phone:$("candidatePhone").value.trim(),batch:$("candidateBatch").value.trim(),guardianContact:$("candidateGuardian").value.trim(),amountDue:Number($("candidateFeesDue").value||0),amountPaid:Number($("candidateFeesPaid").value||0),dueDate:$("candidateDueDate").value};if(!body.email||body.password.length<12)throw new Error("Enter a valid email and a password of at least 12 characters.");const d=await request("/api/admin/candidates",{method:"POST",body:JSON.stringify(body)});["candidateEmail","candidatePassword","candidateName","candidatePhone","candidateGuardian"].forEach(id=>$(id).value="");status("candidateStatus","Account created for "+d.user.email+". Share the temporary password privately.","ok");await loadStudents();await loadFees()}catch(e){status("candidateStatus",e.message,"bad")}}
async function loadFees(){if(user?.role!=="admin")return;try{const d=await request("/api/admin/fees");$("feesList").replaceChildren();if(!d.fees.length){$("feesList").textContent="No student fee records yet.";return}d.fees.forEach(f=>{const card=document.createElement("div");card.className="videoCard";const h=document.createElement("b");h.textContent=(f.full_name||f.email)+" · "+f.email;const due=document.createElement("input"),paid=document.createElement("input"),date=document.createElement("input"),note=document.createElement("input");due.type="number";due.min="0";due.value=f.amount_due;paid.type="number";paid.min="0";paid.value=f.amount_paid;date.type="date";date.value=f.due_date||"";note.value=f.note||"";note.placeholder="Fee note";const grid=document.createElement("div");grid.className="fieldgrid";[[ "Total fees (₹)",due],["Paid (₹)",paid],["Due date",date],["Note",note]].forEach(([label,input])=>{const l=document.createElement("label");l.textContent=label;l.append(input);grid.append(l)});const info=document.createElement("p");info.className="muted";info.textContent="Outstanding: ₹"+Math.max(0,Number(f.amount_due)-Number(f.amount_paid));const btn=makeButton("Save fee record",async()=>{try{const r=await request("/api/admin/fees/"+f.user_id,{method:"PUT",body:JSON.stringify({amountDue:Number(due.value),amountPaid:Number(paid.value),dueDate:date.value,note:note.value})});info.textContent="Outstanding: ₹"+r.outstanding+" · Saved";info.style.color="green";await loadStudents()}catch(e){info.textContent=e.message;info.style.color="#ad3333"}});card.append(h,grid,info,btn);$("feesList").append(card)})}catch(e){globalMessage(e.message,true)}}
async function loadStudentFees(){try{const d=await request("/api/student/fees"),f=d.fees;$("studentFeeSummary").replaceChildren();[["Total fees","₹"+f.amount_due],["Paid","₹"+f.amount_paid],["Outstanding","₹"+Math.max(0,f.amount_due-f.amount_paid)]].forEach(([label,value])=>{const el=document.createElement("div");el.className="metric";const b=document.createElement("b"),sp=document.createElement("span");b.textContent=value;sp.textContent=label;el.append(b,sp);$("studentFeeSummary").append(el)});$("studentFeeNote").textContent=(f.note||"Please contact administration to confirm your fee status.")+(f.due_date?" · Due date: "+f.due_date:"")}catch(e){globalMessage(e.message,true)}}
async function loadVideos(isAdmin){try{const d=await request("/api/videos"),rows=d.videos||[];const target=$(isAdmin?"adminVideoList":"studentVideoList");target.replaceChildren();if(!rows.length){target.textContent=isAdmin?"No video links added yet.":"No videos have been shared with your batch yet.";return}rows.forEach(v=>{const card=document.createElement("div");card.className="videoCard";const h=document.createElement("b");h.textContent=v.title;const meta=document.createElement("p");meta.textContent=v.subject+" · "+v.batch;const desc=document.createElement("p");desc.textContent=v.description||"Lesson video";const link=document.createElement("a");link.href=v.url;link.target="_blank";link.rel="noopener noreferrer";link.textContent="Open lesson video ↗";card.append(h,meta,desc,link);if(isAdmin)card.append(document.createElement("br"),makeButton("Remove link",async()=>{if(!confirm("Remove this video link?"))return;try{await request("/api/admin/videos/"+v.id,{method:"DELETE"});loadVideos(true)}catch(e){globalMessage(e.message,true)}}, "danger"));target.append(card)})}catch(e){globalMessage(e.message,true)}}
