async function loadAnalytics(){if(user?.role!=="admin")return;try{const d=await request("/api/admin/analytics");renderItems("subjectAnalytics",d.bySubject.map(x=>({title:x.subject,desc:x.accuracy+"% accuracy · "+x.correct+" correct · "+x.wrong+" wrong",tag:x.answers+" answers"})));renderItems("chapterAnalytics",d.byChapter.map(x=>({title:x.subject+" · "+(x.chapter||"Unspecified chapter"),desc:x.correct+" correct of "+x.answers+" answered",tag:x.answers+" answers"})));renderItems("scoreTrend",d.scoreTrend.map(x=>({title:x.day,desc:"Average score "+x.average_score,tag:x.attempts+" attempts"})))}catch(e){globalMessage(e.message,true)}}
async function loadStudentAnalysis(){try{const d=await request("/api/student/analysis"),rows=d.sessions.filter(s=>s.status==="submitted");$("studentAnalysisMetrics").replaceChildren();[["Tests submitted",rows.length],["Average score",rows.length?Math.round(rows.reduce((a,s)=>a+(s.score||0),0)/rows.length):"—"],["Latest score",rows.length?(rows[0].score??"—"):"—"]].forEach(([label,value])=>{const el=document.createElement("div");el.className="metric";const b=document.createElement("b"),sp=document.createElement("span");b.textContent=value;sp.textContent=label;el.append(b,sp);$("studentAnalysisMetrics").append(el)});renderItems("studentAnalysisList",d.sessions.map(s=>({title:s.exam_title,desc:s.status+" · "+s.started_at+(s.submitted_at?" · submitted "+s.submitted_at:""),tag:s.status==="submitted"?"Score "+(s.score??0):"In progress",kind:s.status==="submitted"?"green":"amber",action:s.status==="submitted"?makeButton("View report",()=>viewReport(s.id)) : null})));renderItems("studentRecent",rows.slice(0,4).map(s=>({title:s.exam_title,desc:s.submitted_at||s.started_at,tag:"Score "+(s.score??0),kind:"green"})))}catch(e){globalMessage(e.message,true)}}
