async function loadStorageStatus(){try{const d=await request("/api/admin/dashboard-storage");if(!d.configured){status("storageStatus","GitHub persistence is NOT configured. Any data on the free Render filesystem may disappear on restart or redeploy. Create a separate private data repository and configure the six GITHUB_STORAGE_* environment variables.","warn")}else{status("storageStatus","Encrypted GitHub database snapshots are enabled. Last backup: "+(d.lastBackupAt||"waiting for first change")+(d.lastError?" · Last error: "+d.lastError:""),d.lastError?"bad":"ok")}}catch(e){status("storageStatus",e.message,"bad")}}
async function exportCsv(){try{const r=await fetch(api+"/api/admin/reports/export.csv",{headers:{Authorization:"Bearer "+token}});const d=await r.clone().json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Export failed");const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="proctorguard-sessions.csv";a.click();URL.revokeObjectURL(url)}catch(e){globalMessage(e.message,true)}}
function startExam(exam){pendingExam=exam;["consentCamera","consentMic","consentLive"].forEach(id=>$(id).checked=false);status("consentStatus","All three consent boxes must be checked to start a proctored test.","");$("consentModal").classList.remove("hide")}
async function confirmExamConsent(){if(!pendingExam)return;if(!$("consentCamera").checked||!$("consentMic").checked||!$("consentLive").checked){status("consentStatus","Please check all three consent boxes before continuing.","bad");return}if(!navigator.mediaDevices?.getUserMedia){status("consentStatus","This browser does not support camera/microphone access. Open the test site in Safari or Chrome.","bad");return}const exam=pendingExam;status("consentStatus","Requesting camera and microphone permission…","");try{camStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user",width:{ideal:640},height:{ideal:480}},audio:{echoCancellation:true,noiseSuppression:true}});examMediaConsent=true;const d=await request("/api/exams/"+exam.id+"/sessions",{method:"POST",body:"{}"});active=d;answers=d.questions.map(()=>null);marked=new Set();visitedQuestions=new Set();questionIndex=0;paletteFilter="All";deadline=Date.now()+d.session.durationMinutes*60000;$("consentModal").classList.add("hide");$("portal").classList.add("hide");$("examView").classList.remove("hide");$("examView").classList.remove("previewHidden");$("hidePreview").textContent="Hide my preview";$("toggleExamMic").textContent="Mute microphone";$("toggleExamCamera").textContent="Turn camera off";renderExamQuestion();renderExamPalette();await startProctor();await sendEvent("monitoring_started","info","Student granted camera, microphone and live-call consent at test entry; face checks remain advisory.");startLiveSignalPolling();startStudentChatPolling();tick=setInterval(()=>{const remain=Math.max(0,Math.ceil((deadline-Date.now())/1000));$("examTimer").textContent=String(Math.floor(remain/60)).padStart(2,"0")+":"+String(remain%60).padStart(2,"0");if(remain<=0){clearInterval(tick);submitExam(true)}},1000);pendingExam=null}catch(e){if(camStream){camStream.getTracks().forEach(t=>t.stop());camStream=null}examMediaConsent=false;status("consentStatus","Could not start the test: "+e.message+". Check browser permissions and try again.","bad")}}
function cancelExamConsent(){$("consentModal").classList.add("hide");pendingExam=null}
function renderExamQuestion(){const q=active.questions[questionIndex];visitedQuestions.add(questionIndex);$("examSubject").textContent=q.subject.toUpperCase();$("examCounter").textContent="Question "+(questionIndex+1)+" of "+active.questions.length;$("examPrompt").textContent=q.prompt;$("examOptions").replaceChildren();q.options.forEach((o,i)=>{const label=document.createElement("label");label.className="option";const radio=document.createElement("input");radio.type="radio";radio.name="answer";radio.checked=answers[questionIndex]===i;const span=document.createElement("span");span.textContent=String.fromCharCode(65+i)+". "+o;radio.onchange=()=>saveAnswer(i);label.append(radio,span);$("examOptions").append(label)});$("examPrev").disabled=questionIndex===0;$("examNext").textContent=questionIndex===active.questions.length-1?"Last question →":"Save & next →";$("markReview").textContent=marked.has(questionIndex)?"★ Marked for review":"☆ Mark review"}
async function saveAnswer(value){answers[questionIndex]=value;status("saveState","Saving answer…");try{await request("/api/sessions/"+active.session.id+"/answers",{method:"PUT",body:JSON.stringify({questionId:active.questions[questionIndex].id,selectedIndex:value,markedReview:marked.has(questionIndex)})});status("saveState","Answer saved","ok");renderExamPalette()}catch(e){status("saveState","Save failed: "+e.message,"bad")}}
async function clearAnswer(){answers[questionIndex]=null;try{await request("/api/sessions/"+active.session.id+"/answers",{method:"PUT",body:JSON.stringify({questionId:active.questions[questionIndex].id,selectedIndex:null,markedReview:marked.has(questionIndex)})});renderExamQuestion();renderExamPalette();status("saveState","Answer cleared and saved","ok")}catch(e){status("saveState",e.message,"bad")}}
async function toggleReview(){if(marked.has(questionIndex))marked.delete(questionIndex);else marked.add(questionIndex);try{await request("/api/sessions/"+active.session.id+"/answers",{method:"PUT",body:JSON.stringify({questionId:active.questions[questionIndex].id,selectedIndex:answers[questionIndex],markedReview:marked.has(questionIndex)})});renderExamQuestion();renderExamPalette()}catch(e){globalMessage(e.message,true)}}
function renderExamPalette(){$("examPalette").replaceChildren();active.questions.forEach((q,i)=>{if(paletteFilter!=="All"&&q.subject!==paletteFilter)return;const b=document.createElement("button");b.textContent=i+1;let cls=answers[i]!==null?(marked.has(i)?"answered-review":"answered"):(marked.has(i)?"review":(visitedQuestions.has(i)?"not-answered":"not-visited"));b.className=cls+(i===questionIndex?" current":"");b.title="Q"+(i+1)+" · "+q.subject+" · "+(answers[i]!==null?(marked.has(i)?"Answered + review":"Answered"):(marked.has(i)?"Marked for review":(visitedQuestions.has(i)?"Not answered":"Not visited")));b.onclick=()=>goToQuestion(i);$("examPalette").append(b)});document.querySelectorAll("[data-subject-filter]").forEach(b=>{const selected=b.dataset.subjectFilter===paletteFilter;b.classList.toggle("secondary",!selected)})}
function goToQuestion(i){if(!active||i<0||i>=active.questions.length)return;questionIndex=i;if(paletteFilter!=="All"&&active.questions[i].subject!==paletteFilter)paletteFilter=active.questions[i].subject;renderExamQuestion();renderExamPalette()}
function waitForIce(pc,timeout=8000){if(pc.iceGatheringState==="complete")return Promise.resolve();return new Promise(resolve=>{let finished=false;const done=()=>{if(finished)return;finished=true;clearTimeout(timer);pc.removeEventListener("icegatheringstatechange",check);resolve()};const check=()=>{if(pc.iceGatheringState==="complete")done()};const timer=setTimeout(done,timeout);pc.addEventListener("icegatheringstatechange",check)})}
function startLiveSignalPolling(){if(livePollTimer)clearInterval(livePollTimer);livePollTimer=setInterval(pollLiveOffers,2500);pollLiveOffers()}
async function pollLiveOffers(){if(!active||user?.role!=="candidate"||!active.session?.id||pollingLiveOffers)return;pollingLiveOffers=true;try{const d=await request("/api/sessions/"+active.session.id+"/live-offers");for(const offer of (d.offers||[])){if(seenLiveOffers.has(offer.id))continue;seenLiveOffers.add(offer.id);if(!examMediaConsent){await declineLiveOffer(offer);continue}updateStudentCallBanner("Connecting to "+(offer.mode==="voice"?"an audio call":"a video call")+" with the administrator…");await acceptLiveOffer(offer)}}catch{}finally{pollingLiveOffers=false}}
function updateStudentCallBanner(message){const bar=$("liveRequestBanner"),txt=$("liveRequestText"),actions=$("liveRequestActions");if(!bar||!txt||!actions)return;txt.textContent=message||("Live calls active: "+studentLivePeers.size+". You can mute your microphone, disable your camera, or end every live call.");actions.replaceChildren();actions.append(makeButton(camStream?.getAudioTracks().some(t=>t.enabled)?"Mute microphone":"Unmute microphone",toggleExamMic,"secondary"),makeButton(camStream?.getVideoTracks().some(t=>t.enabled)?"Turn camera off":"Turn camera on",toggleExamCamera,"secondary"),makeButton("End all live calls",endAllStudentCalls,"danger"));bar.classList.toggle("hide",studentLivePeers.size===0&&!message)}
async function declineLiveOffer(offer){try{await request("/api/sessions/"+active.session.id+"/live-offers/"+offer.id+"/answer",{method:"POST",body:JSON.stringify({declined:true})})}catch{}}
async function acceptLiveOffer(offer){if(!camStream||!camStream.getAudioTracks().some(t=>t.readyState==="live")){status("proctorStatus","Microphone is unavailable for this call.","bad");await declineLiveOffer(offer);return}let pc;try{pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});await pc.setRemoteDescription({type:"offer",sdp:offer.offer_sdp});const tracks=offer.mode==="voice"?camStream.getAudioTracks():camStream.getTracks();tracks.filter(t=>t.readyState==="live").forEach(track=>pc.addTrack(track,camStream));studentLivePeers.set(offer.id,pc);pc.onconnectionstatechange=()=>{if(["failed","closed"].includes(pc.connectionState)){studentLivePeers.delete(offer.id);try{pc.close()}catch{}if(active)updateStudentCallBanner()}};const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await waitForIce(pc);await request("/api/sessions/"+active.session.id+"/live-offers/"+offer.id+"/answer",{method:"POST",body:JSON.stringify({answerSdp:pc.localDescription.sdp})});status("proctorStatus",(offer.mode==="voice"?"Voice":"Video")+" call connected or connecting with administrator.","ok");updateStudentCallBanner()}catch(e){if(pc)pc.close();studentLivePeers.delete(offer.id);status("proctorStatus","Live call could not connect: "+e.message,"warn");await declineLiveOffer(offer);updateStudentCallBanner()}}
function toggleExamMic(){if(!camStream)return;const tracks=camStream.getAudioTracks(),enabled=tracks.some(t=>t.enabled);tracks.forEach(t=>t.enabled=!enabled);$("toggleExamMic").textContent=enabled?"Unmute microphone":"Mute microphone";updateStudentCallBanner()}
function toggleExamCamera(){if(!camStream)return;const tracks=camStream.getVideoTracks(),enabled=tracks.some(t=>t.enabled);tracks.forEach(t=>t.enabled=!enabled);$("toggleExamCamera").textContent=enabled?"Turn camera on":"Turn camera off";if(active)status("proctorStatus",enabled?"Camera turned off by you. You can turn it on again at any time.":"Camera enabled; advisory face checks may resume.","warn");updateStudentCallBanner()}
function togglePreview(){const exam=$("examView");const hidden=exam.classList.toggle("previewHidden");$("hidePreview").textContent=hidden?"Show my preview":"Hide my preview"}
function endAllStudentCalls(){for(const pc of studentLivePeers.values())try{pc.close()}catch{}studentLivePeers.clear();updateStudentCallBanner();status("proctorStatus","You ended all live calls. Camera and microphone remain available for the test until you turn them off or submit.","warn")}
async function ensureAdminCallMedia(mode){if(!adminAudioStream||!adminAudioStream.getAudioTracks().some(t=>t.readyState==="live"))adminAudioStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});if(mode==="video"&&(!adminVideoStream||!adminVideoStream.getVideoTracks().some(t=>t.readyState==="live")))adminVideoStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:"user",width:{ideal:640},height:{ideal:480}}});const tracks=[...adminAudioStream.getAudioTracks(),...(mode==="video"?adminVideoStream.getVideoTracks():[])];return new MediaStream(tracks)}
function stopAdminMediaIfIdle(){if(adminLivePeers.size)return;if(adminAudioStream){adminAudioStream.getTracks().forEach(t=>t.stop());adminAudioStream=null}if(adminVideoStream){adminVideoStream.getTracks().forEach(t=>t.stop());adminVideoStream=null}}
function endAdminCall(sessionId){const entry=adminLivePeers.get(sessionId);if(entry){try{entry.pc.close()}catch{}entry.card?.remove();adminLivePeers.delete(sessionId)}stopAdminMediaIfIdle();if(!$("liveVideos").children.length){const p=document.createElement("p");p.className="muted";p.textContent="No live calls active.";$("liveVideos").append(p)}}
function endAllAdminCalls(){[...adminLivePeers.keys()].forEach(endAdminCall);status("adminCommStatus","All calls ended.","ok")}
async function startAdminCall(target,mode){if(!window.RTCPeerConnection){status("adminCommStatus","This browser does not support WebRTC calls.","bad");return}try{const d=await request("/api/admin/live"),sessions=d.sessions||[],selected=target||$("adminCommTarget").value;let recipients=selected==="all"?sessions:sessions.filter(x=>x.id===selected);if(!recipients.length)throw new Error("No active test session matches that recipient.");if(selected==="all"&&recipients.length>12)throw new Error("This free peer-to-peer prototype can call up to 12 active test sessions at once. Large group calls need a media relay/SFU service.");const stream=await ensureAdminCallMedia(mode);const results=await Promise.all(recipients.map(session=>startAdminCallForSession(session,mode,stream)));const ok=results.filter(Boolean).length;status("adminCommStatus",(mode==="voice"?"Voice":"Video")+" call started for "+ok+" of "+recipients.length+" selected active session(s). Each student sees a call indicator and can end calls.","ok")}catch(e){status("adminCommStatus",e.message,"bad")}}
async function startAdminCallForSession(session,mode,stream){if(adminLivePeers.has(session.id)){return false}const feeds=$("liveVideos");const empty=feeds.querySelector("p.muted");if(empty)feeds.replaceChildren();const card=document.createElement("div");card.className="videoCard";card.dataset.session=session.id;const title=document.createElement("b");title.textContent=(session.full_name||session.email)+" · "+(mode==="voice"?"Voice call":"Video call");const state=document.createElement("p");state.textContent="Sending call invitation…";const video=document.createElement("video");video.autoplay=true;video.playsInline=true;video.muted=true;video.style.cssText="width:100%;max-height:230px;background:#17243b;border-radius:10px;"+(mode==="video"?"":"display:none");const audio=document.createElement("audio");audio.autoplay=true;audio.playsInline=true;audio.style.cssText=mode==="voice"?"width:100%":"display:none";const close=makeButton("End call",()=>endAdminCall(session.id),"danger");card.append(title,state,video,audio,close);feeds.append(card);let pc,offerId;try{pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});adminLivePeers.set(session.id,{pc,card,video,audio,state,mode});stream.getTracks().forEach(track=>pc.addTrack(track,stream));pc.ontrack=ev=>{const remote=ev.streams?.[0]||new MediaStream([ev.track]);if(mode==="video"){video.srcObject=remote;video.play().catch(()=>{})}else{audio.srcObject=remote;audio.play().catch(()=>{})}state.textContent="Connected · not recorded by ProctorGuard"};pc.onconnectionstatechange=()=>{if(["failed","disconnected"].includes(pc.connectionState))state.textContent="Connection lost or blocked by network. Try again or check network compatibility.";if(pc.connectionState==="connected")state.textContent="Connected · "+(mode==="voice"?"audio":"audio/video")+" active"};const offer=await pc.createOffer();await pc.setLocalDescription(offer);await waitForIce(pc);const created=await request("/api/admin/live/"+session.id+"/offers",{method:"POST",body:JSON.stringify({offerSdp:pc.localDescription.sdp,mode})});offerId=created.offerId;state.textContent="Call sent · waiting for student connection…";for(let i=0;i<25;i++){await new Promise(r=>setTimeout(r,1000));if(pc.connectionState==="closed")return false;const result=await request("/api/admin/live/"+session.id+"/offers/"+offerId+"/answer");if(result.offer.status==="declined"){state.textContent="Call was declined.";pc.close();adminLivePeers.delete(session.id);return false}if(result.offer.answer_sdp){await pc.setRemoteDescription({type:"answer",sdp:result.offer.answer_sdp});state.textContent="Answer received · connecting…";return true}}state.textContent="No answer yet. Confirm the student is still in their test and has consented.";return false}catch(e){state.textContent="Call unavailable: "+e.message;if(pc)pc.close();adminLivePeers.delete(session.id);return false}}
async function selectAdminChat(sessionId){$("adminCommTarget").value=sessionId;await loadAdminChat();$("adminMessageInput").focus()}
function renderChatMessages(targetId,rows){targetId.replaceChildren();if(!rows.length){const p=document.createElement("p");p.className="muted";p.textContent="No messages yet.";targetId.append(p);return}rows.forEach(m=>{const item=document.createElement("div");item.className="chatMessage"+(m.sender_id===user?.id?" mine":"");const meta=document.createElement("small"),body=document.createElement("div");meta.textContent=(m.sender_id===user?.id?"You":m.sender_role==="admin"?"Administrator":(m.sender_email||"Student"))+" · "+new Date(m.created_at).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"});body.textContent=m.body;item.append(meta,body);targetId.append(item)});targetId.scrollTop=targetId.scrollHeight}
