async function startProctor(){try{if(!camStream)throw new Error("Camera/microphone consent is not available.");$("proctorVideo").srcObject=camStream;$("proctorPill").textContent="Camera & mic ready";$("proctorStatus").textContent="Loading face detector…";if(!window.faceapi)throw new Error("Face detector library did not load");await faceapi.nets.ssdMobilenetv1.loadFromUri("https://justadudewhohacks.github.io/face-api.js/models/");faceModelReady=true;$("proctorStatus").className="status ok";$("proctorStatus").textContent="Face detector ready. Processing stays in this tab; live calls begin only when the administrator starts one.";proctorTimer=setInterval(checkProctor,2500)}catch(e){faceModelReady=false;$("proctorPill").textContent="Media consented";$("proctorStatus").className="status warn";$("proctorStatus").textContent="Camera/mic are available, but the advisory face detector could not start: "+e.message;await sendEvent("camera_interrupted","medium","Face detector could not start: "+String(e.message||e).slice(0,300))}}
async function checkProctor(){if(!active||!faceModelReady||proctorBusy)return;proctorBusy=true;try{const v=$("proctorVideo");if(!camStream||camStream.getVideoTracks().every(t=>t.readyState!=="live")){if(Date.now()-(alertTimes.camera||0)>20000){alertTimes.camera=Date.now();await sendEvent("camera_interrupted","medium","Camera stream is no longer active")}$("proctorStatus").className="status bad";$("proctorStatus").textContent="Camera interrupted";return}if(!v.videoWidth)return;const faces=await faceapi.detectAllFaces(v,new faceapi.SsdMobilenetv1Options({minConfidence:.55}));if(!faces.length){absenceFrames++;multiFrames=0;$("proctorStatus").className="status warn";$("proctorStatus").textContent="No face detected · please centre your face";if(absenceFrames>=3&&Date.now()-(alertTimes.absent||0)>20000){alertTimes.absent=Date.now();await sendEvent("face_absent","medium","No face detected across repeated checks")}}else if(faces.length>1){multiFrames++;absenceFrames=0;$("proctorStatus").className="status warn";$("proctorStatus").textContent="Multiple faces detected ("+faces.length+")";if(multiFrames>=2&&Date.now()-(alertTimes.multi||0)>20000){alertTimes.multi=Date.now();await sendEvent("multiple_faces","medium","More than one face detected in repeated checks")}}else{absenceFrames=0;multiFrames=0;$("proctorStatus").className="status ok";$("proctorStatus").textContent="One face detected · presence signal only"}}catch(e){$("proctorStatus").className="status warn";$("proctorStatus").textContent="Face analysis temporarily unavailable"}finally{proctorBusy=false}}
function stopProctor(){if(proctorTimer)clearInterval(proctorTimer);proctorTimer=null;if(camStream){camStream.getTracks().forEach(t=>t.stop());camStream=null}faceModelReady=false}
