$("connect").onclick=connect;$("loginBtn").onclick=login;$("logout").onclick=logout;$("createCandidate").onclick=createCandidate;$("createExam").onclick=createExam;$("importBank").onclick=importBank;$("publishExam").onclick=publishExam;$("reloadDrafts").onclick=()=>loadDrafts();$("refreshExams").onclick=loadExams;$("refreshAdminExams").onclick=loadExams;$("refreshStudents").onclick=loadStudents;$("refreshFees").onclick=loadFees;$("refreshLive").onclick=loadLive;$("refreshAnalytics").onclick=loadAnalytics;$("refreshStudentVideos").onclick=()=>loadVideos(false);$("refreshAdminVideos").onclick=()=>loadVideos(true);$("addVideo").onclick=addVideo;$("saveAccount").onclick=saveAccount;$("exportCsv").onclick=exportCsv;$("exportCsv2").onclick=exportCsv;$("closePreview").onclick=()=>$("previewModal").classList.add("hide");$("backToExams").onclick=backToPortal;$("exitExam").onclick=()=>submitExam(false);$("examPrev").onclick=()=>{if(questionIndex>0){questionIndex--;renderExamQuestion();renderExamPalette()}};$("examNext").onclick=()=>{if(questionIndex<active.questions.length-1){questionIndex++;renderExamQuestion();renderExamPalette()}};$("markReview").onclick=toggleReview;$("clearAnswer").onclick=clearAnswer;$("submitExam").onclick=()=>submitExam(false);$("downloadReport").onclick=()=>{if(!currentReport)return;const blob=new Blob([JSON.stringify(currentReport,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="proctorguard-report-"+currentReport.sessionId+".json";a.click();URL.revokeObjectURL(url)};
document.querySelectorAll(".nav button[data-page]").forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll("[data-goto]").forEach(b=>b.onclick=()=>showPage(b.dataset.goto));document.addEventListener("visibilitychange",()=>{if(document.hidden&&active)sendEvent("tab_hidden","medium","Browser tab became inactive; may have legitimate causes.")});window.addEventListener("beforeunload",e=>{if(active&&!$("reportView").classList.contains("hide"))return;if(active){e.preventDefault();e.returnValue=""}});
$("demoHelp").onclick=()=>globalMessage("V3 stores app code in GitHub. To preserve student records across free-host restarts, configure encrypted snapshots to a separate private GitHub data repository. Never put passwords, tokens or unencrypted student data into the code repository.",false);
window.addEventListener("DOMContentLoaded",()=>{$("apiOrigin").value=window.location.origin;connect()});
